#include "camera.hpp"
#include "common.hpp"
#include "contours.hpp"
#include "laser.hpp"
#include "liquid.hpp"
#include "options.hpp"
#include <opencv2/highgui.hpp>
#include <opencv2/imgproc.hpp>
#include <algorithm>
#include <cmath>
#include <stdexcept>
#include <atomic>
#include <csignal>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <thread>
#include <vector>
using namespace liquid;

static volatile std::sig_atomic_t interrupted=0;
static void signalHandler(int){interrupted=1;}
struct Timings{double physics=0,field=0,contour=0,path=0,gui=0,processing=0,interval=0;int missed=0,loops=0;};

static void preview(const CameraFrame&camera,const std::vector<Loop>&loops,const Options&o){cv::Mat gray;camera.depth.convertTo(gray,CV_8U,-255.0/4000.0,255.0);gray.setTo(0,camera.depth==0);cv::Mat large,display;cv::resize(gray,large,{480,480},0,0,cv::INTER_LINEAR);cv::cvtColor(large,display,cv::COLOR_GRAY2BGR);if(!camera.mask.empty()){cv::Mat maskLarge;cv::resize(camera.mask,maskLarge,{480,480},0,0,cv::INTER_NEAREST);display.setTo(cv::Scalar(50,50,170),maskLarge);}auto pixel=[&](V p){float nx=(p.x+o.sim.extent)/(2.f*o.sim.extent),ny=(p.y+o.sim.extent)/(2.f*o.sim.extent);return cv::Point(int(std::lround(nx*479.f)),int(std::lround(ny*479.f)));};cv::rectangle(display,pixel(o.sim.lower),pixel(o.sim.upper),cv::Scalar(255,180,0),1,cv::LINE_AA);for(const auto&loop:loops){std::vector<cv::Point> points;points.reserve(loop.size());for(V p:loop)points.push_back(pixel(p));cv::polylines(display,points,true,cv::Scalar(0,255,0),2,cv::LINE_AA);}cv::putText(display,cv::format("Depth %.1f-%.1fcm Coh %.2f Rep %.2f",o.minMM/10.f,o.maxMM/10.f,o.sim.cohesion,o.sim.repulsion),{10,24},cv::FONT_HERSHEY_SIMPLEX,.48,{255,255,255},1,cv::LINE_AA);if(!camera.valid)cv::putText(display,"DEPTH INVALID / TOO CLOSE - LASER BLANK",{10,455},cv::FONT_HERSHEY_SIMPLEX,.45,{0,255,255},1,cv::LINE_AA);cv::imshow("CPU Liquid Laser",display);}

int main(int argc,char**argv){Options o;try{o=parseOptions(argc,argv);}catch(const std::exception&e){std::cerr<<e.what()<<"\nRun laser --help\n";return 2;}std::signal(SIGINT,signalHandler);std::signal(SIGTERM,signalHandler);cv::setNumThreads(1);cv::setUseOptimized(true);std::atomic<bool> run{true};Latest<CameraFrame> camera;Latest<OutputFrame> output;Counters counters;std::mutex errorMutex;std::string cameraError,laserError,mainError;std::thread capture,laser;std::cout<<"CPU liquid: particles="<<o.sim.particles<<" field="<<o.sim.field<<" target="<<o.fps<<"Hz GUI="<<(o.gui?"on":"off")<<" laser="<<(o.noLaser?"off":"LaserDock 30000pps")<<"\nDepth="<<o.minMM/10.f<<".."<<o.maxMM/10.f<<"cm cohesion="<<o.sim.cohesion<<" repulsion="<<o.sim.repulsion<<" threshold="<<o.sim.threshold<<'\n';
 try{capture=std::thread(captureLoop,std::cref(o),std::ref(run),std::ref(camera),std::ref(counters),std::ref(cameraError),std::ref(errorMutex),std::ref(interrupted));auto waitStart=Clock::now();while(run&&!interrupted&&!camera.get()){if(seconds(waitStart,Clock::now())>10)throw std::runtime_error("No depth frame within 10 seconds");std::this_thread::sleep_for(std::chrono::milliseconds(10));}if(!run||interrupted)throw std::runtime_error("Camera startup stopped");if(!o.noLaser)laser=std::thread(laserLoop,std::cref(o),std::ref(run),std::cref(camera),std::cref(output),std::ref(counters),std::ref(laserError),std::ref(errorMutex),std::ref(interrupted));Simulation simulation(o.sim);Grid field(o.sim.field,o.sim.extent);Contours contours;ScanConfig scan{30000/o.fps,o.scale,o.flipX,o.flipY};V anchor{};auto began=Clock::now(),next=began,previous=began,report=began;auto period=std::chrono::duration_cast<Clock::duration>(std::chrono::duration<double>(1.0/o.fps));std::vector<Timings> window;window.reserve(180);uint64_t lastCamera=counters.cameraFrames.load(),lastSubmitted=counters.submitted.load(),lastErrors=counters.laserErrors.load(),guiSequence=0;bool first=true,cameraUnavailable=false;if(o.gui)cv::namedWindow("CPU Liquid Laser",cv::WINDOW_AUTOSIZE);
  while(run&&!interrupted){std::this_thread::sleep_until(next);auto start=Clock::now();if(o.duration>0&&seconds(began,start)>=o.duration)break;auto body=camera.get();bool unavailable=!body||!body->valid||seconds(body->captured,start)>.25;if(unavailable){if(!cameraUnavailable){std::cerr<<"WARNING: depth unavailable/stale. Blanking laser and pausing fluid...\n";cameraUnavailable=true;}auto blank=std::make_shared<OutputFrame>();blank->samples.assign(scan.samples,Sample{anchor,false});blank->made=Clock::now();blank->cameraTime=body?body->captured:Clock::time_point{};output.set(blank);if(o.gui&&body&&body->seq!=guiSequence){preview(*body,{},o);guiSequence=body->seq;}if(o.gui){int key=cv::waitKey(1)&255;if(key==27||key=='q')run=false;}next=Clock::now()+period;previous=Clock::now();first=true;std::this_thread::sleep_for(std::chrono::milliseconds(5));continue;}if(cameraUnavailable){std::cerr<<"Depth recovered.\n";cameraUnavailable=false;next=Clock::now();previous=next;first=true;}
   Timings t;t.interval=first?1000.0/o.fps:millis(previous,start);first=false;previous=start;auto p=Clock::now();for(int k=0;k<o.sim.substeps;++k)simulation.step(1.f/(o.fps*o.sim.substeps),body->obstacle);auto f=Clock::now();t.physics=millis(p,f);simulation.density(field,body->obstacle);auto c=Clock::now();t.field=millis(f,c);auto loops=contours.extract(field,o.sim.threshold,o.sim.minArea,o.sim.maxLoops,o.sim.points,o.sim.smoothing);auto path=Clock::now();t.contour=millis(c,path);t.loops=int(loops.size());auto out=std::make_shared<OutputFrame>();out->samples=planScan(loops,body->obstacle.sdf,scan,anchor);out->cameraTime=body->captured;out->made=Clock::now();output.set(out);auto g=Clock::now();t.path=millis(path,g);if(o.gui&&body->seq!=guiSequence){preview(*body,loops,o);guiSequence=body->seq;}if(o.gui){int key=cv::waitKey(1)&255;if(key==27||key=='q')run=false;if(key=='r')simulation=Simulation(o.sim);}auto finish=Clock::now();t.gui=millis(g,finish);t.processing=millis(start,finish);next+=period;if(finish>next){t.missed=1+int((finish-next)/period);next+=period*t.missed;}window.push_back(t);double elapsed=seconds(report,finish);if(elapsed>=1&&!window.empty()){double ph=0,fd=0,ct=0,pt=0,gu=0,sum=0,inter=0;int over=0,missed=0;std::vector<double> values;for(const auto&a:window){ph+=a.physics;fd+=a.field;ct+=a.contour;pt+=a.path;gu+=a.gui;sum+=a.processing;inter+=a.interval;over+=a.processing>1000.0/o.fps;missed+=a.missed;values.push_back(a.processing);}std::sort(values.begin(),values.end());double n=window.size();auto cam=counters.cameraFrames.load(),sent=counters.submitted.load(),errs=counters.laserErrors.load();size_t p95=std::min(values.size()-1,size_t(std::ceil(n*.95))-1);std::cout<<std::fixed<<std::setprecision(2)<<"cam="<<(cam-lastCamera)/elapsed<<"fps liquid="<<n/elapsed<<"fps work(avg/p95/max)="<<sum/n<<'/'<<values[p95]<<'/'<<values.back()<<"ms physics="<<ph/n<<" field="<<fd/n<<" contour="<<ct/n<<" path="<<pt/n<<" gui="<<gu/n<<" interval="<<inter/n<<"ms over="<<over<<'/'<<window.size()<<" missed="<<missed<<" loops="<<t.loops<<" camera_work="<<counters.cameraMs.load()<<"ms submitted="<<(sent-lastSubmitted)/elapsed<<"pps laser_errors="<<(errs-lastErrors)<<std::endl;lastCamera=cam;lastSubmitted=sent;lastErrors=errs;report=finish;window.clear();}}
 }catch(const std::exception&e){mainError=e.what();}run=false;if(capture.joinable())capture.join();if(laser.joinable())laser.join();if(o.gui)cv::destroyAllWindows();if(!mainError.empty())std::cerr<<"ERROR: "<<mainError<<'\n';if(!cameraError.empty())std::cerr<<"ERROR: "<<cameraError<<'\n';if(!laserError.empty())std::cerr<<"ERROR: "<<laserError<<'\n';std::cout<<"Stopped. Laser errors="<<counters.laserErrors.load()<<'\n';return mainError.empty()&&cameraError.empty()&&laserError.empty()?0:1;}
